def choose_move(observation):
    def clip(v):
        return -1 if v < -1 else (1 if v > 1 else 0)

    def pos(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def step_toward(a, b):
        ax, ay = pos(a)
        bx, by = pos(b)
        return [clip(bx - ax), clip(by - ay)]

    def manhattan(a, b):
        ax, ay = pos(a)
        bx, by = pos(b)
        return abs(bx - ax) + abs(by - ay)

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos(observation.get("self_position", (0, 0)))
    ox, oy = pos(observation.get("opponent_position", (sx, sy)))
    w = observation.get("grid_width", 0) or 0
    h = observation.get("grid_height", 0) or 0
    role = observation.get("self_role", "pursuer")

    if env == "pursuit_evasion":
        if role == "pursuer":
            return step_toward((sx, sy), (ox, oy))
        candidates = [(0, 0), (0, h - 1), (w - 1, 0), (w - 1, h - 1)]
        best = candidates[0]
        best_d = -1
        for c in candidates:
            d = manhattan((ox, oy), c)
            if d > best_d:
                best_d = d
                best = c
        return step_toward((sx, sy), best)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("neutral_cells") or []
        if targets:
            best = targets[0]
            best_d = 10 ** 9
            for t in targets:
                d = manhattan((sx, sy), t)
                if d < best_d:
                    best_d = d
                    best = t
            return step_toward((sx, sy), best)
        if w and h:
            return step_toward((sx, sy), (w // 2, h // 2))
        return [0, 0]

    resources = observation.get("resources") or observation.get("resource_positions") or []
    if resources:
        best = resources[0]
        best_d = 10 ** 9
        for r in resources:
            d = manhattan((sx, sy), r)
            if d < best_d:
                best_d = d
                best = r
        return step_toward((sx, sy), best)

    if manhattan((sx, sy), (ox, oy)) <= 2:
        return step_toward((ox, oy), (sx, sy))

    if w and h:
        return step_toward((sx, sy), (w // 2, h // 2))
    return [0, 0]

